Inline Assembly (GCC __asm__):
#include <stdio.h>

int main() {
    int a = 10, b = 20, result;

    // Basic inline assembly
    __asm__ (
        "mov %1, %%rax\n\t"
        "add %2, %%rax\n\t"
        "mov %%rax, %0"
        : "=r"(result)    // output
        : "r"(a), "r"(b)  // inputs
        : "%rax"          // clobbered registers
    );
    printf("Result: %d\n", result);

    // Using immediate
    __asm__ (
        "imul $3, %0"
        : "=r"(result)
        : "0"(a)
    );
    return 0;
}

